"use strict";
GUIDE_DATA_VI.sections.push({"blocks":[{"level":1,"text":"Vòng đời phát triển phần mềm (Software Development Life Cycle, SDLC)"},{"level":2,"text":"Một framework phát triển phần mềm linh hoạt nhằm tạo ra phần mềm chất lượng cao, chi phí thấp và được kiểm thử kỹ lưỡng"},{"level":2,"text":"Người dùng SDLC lồng ghép các thực hành tốt nhất và bài học kinh nghiệm vào framework để hiệu quả hơn trong mỗi chu kỳ tiếp theo"},{"level":1,"text":"Theo sách giáo khoa chính thức của CompTIA Project+, có 7 giai đoạn trong framework SDLC"},{"level":2,"text":"Lập kế hoạch (Planning)"},{"level":2,"text":"Nơi chúng ta phác thảo dự án và xác định phạm vi (scope) và mục đích của phần mềm"},{"level":2,"text":"Yêu cầu (Requirements)"},{"level":2,"text":"Chúng ta xác định các nguồn lực cần cho dự án và quyết định phần mềm cần làm gì"},{"level":2,"text":"Thiết kế & tạo mẫu (Design & Prototyping)"},{"level":2,"text":"Xác định phần mềm cần hoạt động như thế nào, chẳng hạn như dùng ngôn ngữ lập trình nào, giao thức bảo mật nào và giao diện người dùng hoạt động ra sao"},{"level":2,"text":"Phát triển (Development)"},{"level":2,"text":"Khi phần mềm thực sự được tạo ra"},{"level":2,"text":"Kiểm thử (Testing)"},{"level":2,"text":"Khi các bài kiểm thử được thực hiện để đảm bảo phần mềm hoạt động như mong đợi"},{"level":2,"text":"Triển khai (Deployment)"},{"level":2,"text":"Khi phần mềm đi vào production"},{"level":2,"text":"Vận hành và bảo trì (Operations and Maintenance)"},{"level":2,"text":"Khi phần mềm được hỗ trợ trong suốt thời gian nó còn trong production"},{"level":1,"text":"Vòng đời phát triển phần mềm có thể tuyến tính và tuần tự, lặp và tăng dần, hoặc kết hợp cả hai"},{"level":1,"text":"SDLC có thể áp dụng cho nhiều loại mô hình phát triển"},{"level":2,"text":"Waterfall"},{"level":2,"text":"Mô hình SDLC gốc được tạo ra để mô phỏng các phương pháp Waterfall hiện có"},{"level":2,"text":"SDLC Waterfall phù hợp với các công nghệ đã được xác định trước và các dự án ngắn"},{"level":2,"text":"Lặp (Iterative)"},{"level":2,"text":"Một cách tiếp cận lai giữa mô hình lặp và mô hình tuần tự"},{"level":2,"text":"Xoắn ốc (Spiral)"},{"level":2,"text":"Một mô hình lặp lấy rủi ro làm trung tâm"},{"level":2,"text":"Spiral là mô hình phức tạp nhất và tốn nhiều nguồn lực nhất, và các dự án cần quản lý chi phí và phạm vi một cách quyết liệt"},{"level":2,"text":"Agile"},{"level":2,"text":"Một mô hình lặp, lấy khách hàng làm trung tâm"},{"level":2,"text":"SDLC Agile bao gồm nhiều phản hồi từ khách hàng hơn"},{"level":2,"text":"Các công ty muốn đưa sản phẩm ra thị trường nhanh cũng dùng Agile"},{"level":1,"text":"Điểm mạnh của SDLC"},{"level":2,"text":"SDLC là một framework toàn diện và bao gồm mọi công việc cần thiết"},{"level":1,"text":"Điểm yếu của SDLC"},{"level":2,"text":"Framework SDLC phụ thuộc vào thời gian dành cho việc lập kế hoạch kỹ lưỡng từ trước"}],"id":"g23","part":3,"title":"Vòng đời phát triển phần mềm (Software Development Life Cycle, SDLC)"},{"blocks":[{"level":1,"text":"PRINCE2 là một phương pháp dựa trên quy trình, phổ biến nhất ở Anh, EU, Canada và Úc"},{"level":2,"text":"Nó nhằm kiểm soát các quy trình quản lý dự án bằng cách tạo ra các giai đoạn dự án rõ ràng, xác định rõ vai trò và trách nhiệm, và định nghĩa trước các công việc để quản lý vòng đời dự án"},{"level":1,"text":"PRINCE2 yêu cầu một số vai trò"},{"level":2,"text":"Quản lý nhóm (Team Manager)"},{"level":2,"text":"Một thành viên của nhóm quản lý dự án, tập trung hỗ trợ giám đốc dự án bằng cách giám sát các nhóm và quản lý chất lượng của các sản phẩm đầu ra"},{"level":2,"text":"Ban dự án (Project Board)"},{"level":2,"text":"Phê duyệt nguồn lực và kinh phí, hỗ trợ giám đốc dự án, và chịu trách nhiệm cuối cùng về dự án"},{"level":2,"text":"Ban dự án bao gồm ba vai trò: điều hành (executive), người dùng cấp cao (senior user) và nhà cung cấp cấp cao (senior supplier)"},{"level":2,"text":"Điều hành (Executive)"},{"level":2,"text":"Một thành viên của ban lãnh đạo cấp cao, đại diện cho góc nhìn doanh nghiệp, là thành viên quyết định của ban dự án, và sở hữu luận chứng kinh doanh (business case) của dự án"},{"level":2,"text":"Người dùng cấp cao (Senior User)"},{"level":2,"text":"Đại diện cho góc nhìn của khách hàng"},{"level":2,"text":"Nhà cung cấp cấp cao (Senior Supplier)"},{"level":2,"text":"Đại diện cho góc nhìn của nhà cung cấp hoặc đối tác triển khai"},{"level":1,"text":"PRINCE2 khởi đầu là một phương pháp Waterfall và sau đó đã áp dụng thêm một mô hình Agile bổ trợ"},{"level":1,"text":"Điểm then chốt nằm ở các thực hành tốt nhất mà nó áp đặt, đó là 7 nguyên tắc (principles), 7 chủ đề (themes) và 7 quy trình (processes) của phương pháp này"},{"level":1,"text":"PRINCE2 rất linh hoạt và một trong những điểm mạnh của nó là khả năng tùy biến (customization)"},{"level":1,"text":"7 nguyên tắc thể hiện triết lý của PRINCE2 và giúp định hướng việc ra quyết định"},{"level":1,"text":"Các chủ đề thể hiện các lĩnh vực kiến thức của giám đốc dự án"},{"level":1,"text":"7 quy trình thể hiện các hoạt động phải diễn ra xuyên suốt vòng đời của dự án"},{"level":1,"text":"Khởi sự (Starting up) xem xét luận chứng kinh doanh và xác định tính khả thi của dự án"},{"level":2,"text":"Khởi xướng (Initiating) xác định các khía cạnh của dự án như phạm vi, chi phí, thời gian, rủi ro, chất lượng và lợi ích"},{"level":1,"text":"PRINCE2 rất linh hoạt và có thể áp dụng cho hầu hết mọi dự án"},{"level":2,"text":"Nó duy trì giao tiếp liên tục giữa ban dự án, giám đốc dự án và các nhóm dự án"},{"level":2,"text":"Nó không phù hợp với các công ty không chú trọng tài liệu hóa"},{"level":1,"text":"PRINCE2 là phương pháp quản lý dự án dựa trên quy trình rất phổ biến ở Vương quốc Anh và đang nhanh chóng được chấp nhận tại Hoa Kỳ"},{"level":2,"text":"Nó đòi hỏi sự tham gia của ban lãnh đạo cấp cao nhiều hơn các phương pháp khác, giúp quản lý nguồn lực tốt hơn và giảm rủi ro"}],"id":"g24","part":3,"title":"PRINCE2"},{"blocks":[{"level":1,"text":"Điểm khác biệt rõ rệt nhất giữa Waterfall và Agile là tính linh hoạt"},{"level":1,"text":"Người thực hành Waterfall có thể gọi tính linh hoạt này là sự mơ hồ, còn người ủng hộ Agile mô tả nó là khả năng thích ứng"}],"id":"g25","part":3,"title":"So sánh Waterfall và Agile"},{"blocks":[{"level":1,"text":"Framework dự án bạn chọn có thể ảnh hưởng đến cách phân công vai trò và trách nhiệm trong một dự án"},{"level":1,"text":"Chủ sở hữu sản phẩm (Product Owners)"},{"level":2,"text":"Làm việc trong các nhóm Agile và xác định cách cải thiện sản phẩm, đồng thời chịu trách nhiệm tạo ra sản phẩm có giá trị cao nhất có thể"},{"level":2,"text":"Trách nhiệm của Product Owner"},{"level":2,"text":"Tạo ra một sản phẩm có giá trị"},{"level":2,"text":"Làm việc trong thời gian cố định, chi phí cố định và phạm vi linh hoạt"},{"level":2,"text":"Cung cấp định hướng và tầm nhìn sản phẩm"},{"level":1,"text":"Giám đốc dự án (Project Managers)"},{"level":2,"text":"Dẫn dắt các dự án trong bất kỳ framework nào và duy trì vai trò đó suốt thời gian dự án còn hoạt động"},{"level":2,"text":"Trách nhiệm của giám đốc dự án"},{"level":2,"text":"Quản lý kế hoạch dự án"},{"level":2,"text":"Lịch trình (Schedule)"},{"level":2,"text":"Tài liệu khởi xướng và đóng dự án (Initiation and closing documents)"},{"level":2,"text":"Đo lường tiến độ của dự án"},{"level":2,"text":"Quản lý rủi ro dự án"},{"level":2,"text":"Làm việc trong thời gian cố định, chi phí cố định và phạm vi cố định"},{"level":1,"text":"Quản lý sản phẩm (Product Managers)"},{"level":2,"text":"Xác định chiến lược sản phẩm và tạo lộ trình (roadmaps) để thể hiện sản phẩm sẽ cải thiện và thay đổi như thế nào theo thời gian"},{"level":1,"text":"Cả giám đốc dự án và chủ sở hữu sản phẩm đều có trách nhiệm chồng chéo và các lợi ích chung đặc thù"},{"level":2,"text":"Cả hai đều chịu trách nhiệm giao tiếp trực tiếp với các bên liên quan, dẫn dắt nhóm của mình và duy trì danh sách công việc"},{"level":1,"text":"Khi dẫn dắt một nhóm"},{"level":2,"text":"Chủ sở hữu sản phẩm chia sẻ định hướng về mục đích và tầm nhìn của sản phẩm"},{"level":2,"text":"Giám đốc dự án xây dựng sự ủng hộ cho dự án và cách tiếp cận dự án"},{"level":1,"text":"Khi duy trì danh sách công việc"},{"level":2,"text":"Chủ sở hữu sản phẩm duy trì backlog sản phẩm (product backlog)"},{"level":2,"text":"Giám đốc dự án sử dụng cấu trúc phân rã công việc (work breakdown structure, còn gọi là WBS) hoặc backlog dự án"},{"level":1,"text":"Chủ sở hữu sản phẩm không phải là người quản lý"},{"level":1,"text":"Giám đốc dự án cần quản lý các nhóm và công việc của họ"},{"level":1,"text":"Chủ sở hữu sản phẩm không tham gia vào chi tiết của công việc"},{"level":1,"text":"Các nhóm Agile tự tổ chức và sẽ đảm nhận vai trò chủ động hơn trong việc phân rã công việc, bất kể công việc đó là cho sản phẩm hay dự án"},{"level":1,"text":"Hợp tác với chủ sở hữu sản phẩm có thể giúp công việc của giám đốc dự án dễ dàng hơn"},{"level":1,"text":"Nên làm việc với chủ sở hữu sản phẩm để xây dựng một backlog sản phẩm hợp nhất, bao gồm cả công việc của dự án"},{"level":1,"text":"Nếu một nhóm đã có chủ sở hữu sản phẩm, họ có lẽ đang dùng một phương pháp quản lý dự án Agile"},{"level":1,"text":"Các nhóm không có chủ sở hữu sản phẩm cũng có thể dùng cách tiếp cận quản lý dự án Agile"}],"id":"g26","part":3,"title":"Sở hữu sản phẩm (Product Ownership)"},{"blocks":[{"level":1,"text":"Agile"},{"level":2,"text":"Các nhóm có quy mô nhỏ theo thiết kế, với 3-10 thành viên"},{"level":1,"text":"Waterfall"},{"level":2,"text":"Các nhóm có quy mô lớn và có thể có bất kỳ quy mô nào"},{"level":1,"text":"Scaled Agile"},{"level":2,"text":"Tạo ra một nhóm lớn bằng cách gom nhiều nhóm Agile nhỏ lại với nhau"},{"level":1,"text":"Các nhóm Agile tạo thành một nhóm đa chức năng (cross-functional) gắn bó với dự án trong suốt vòng đời"},{"level":1,"text":"Các thành viên phải đảm nhận nhiều vai trò và có kinh nghiệm rộng"},{"level":1,"text":"Một nhóm Waterfall tập hợp các chuyên gia để hoàn thành công việc"},{"level":1,"text":"Nếu giữ tất cả thành viên trong suốt dự án, hãy chọn một framework Agile"},{"level":1,"text":"Khi cần những cá nhân chuyên môn cao, hãy cân nhắc dùng Waterfall"}],"id":"g27","part":3,"title":"Thành phần nhóm (Team Composition)"},{"blocks":[{"level":1,"text":"Giao tiếp với các bên liên quan (Stakeholder Communication)"},{"level":2,"text":"Giao tiếp với các bên liên quan thay đổi theo từng framework"},{"level":2,"text":"Ví dụ, trong các dự án Waterfall, bên liên quan cung cấp yêu cầu toàn diện ngay từ đầu dự án"},{"level":2,"text":"Đảm bảo yêu cầu của khách hàng, kỳ vọng chất lượng và nhu cầu được hiểu rõ trước khi chuyển sang giai đoạn phát triển của dự án"},{"level":2,"text":"Các dự án Agile thu hút sự tham gia của bên liên quan xuyên suốt toàn bộ dự án"},{"level":2,"text":"Chúng đòi hỏi các bên liên quan có thời gian và động lực để hợp tác và nhận được sản phẩm đáp ứng nhu cầu của họ"},{"level":1,"text":"Kênh giao tiếp (Communication Channels)"},{"level":2,"text":"Trong Waterfall, khách hàng không giao tiếp trực tiếp với các lập trình viên"},{"level":2,"text":"Trong Agile, nhóm phát triển giao tiếp trực tiếp với khách hàng để làm rõ yêu cầu và chia sẻ tiến độ"},{"level":1,"text":"Truyền đạt cập nhật và thay đổi (Communicating updates and changes)"},{"level":2,"text":"Tần suất thay đổi cũng ảnh hưởng đến yêu cầu giao tiếp"},{"level":2,"text":"Các dự án Waterfall đưa vào ít thay đổi, trong khi các dự án Agile đón nhận thay đổi"},{"level":2,"text":"Agile giảm nguy cơ hiểu sai"},{"level":2,"text":"Tốc độ và khối lượng của thay đổi đòi hỏi giao tiếp hiệu quả"},{"level":2,"text":"Các nhóm Agile tạo lịch trình mỗi 1-4 tuần cho các khoảng sprint và có thể đưa thay đổi vào ở mỗi phiên lập kế hoạch"}],"id":"g28","part":3,"title":"Giao tiếp (Communication)"},{"blocks":[{"level":1,"text":"Yêu cầu định hướng dự án"},{"level":2,"text":"Chúng quyết định kết quả của dự án trông như thế nào, hoạt động ra sao và được sử dụng như thế nào"},{"level":1,"text":"Điểm khác biệt chính giữa các phương pháp là thời điểm yêu cầu được tạo ra"},{"level":2,"text":"Trong một dự án Waterfall"},{"level":2,"text":"Thu thập yêu cầu -> Tạo sản phẩm -> Khách hàng đánh giá -> Giai đoạn bảo trì"},{"level":2,"text":"Trong một dự án Agile"},{"level":2,"text":"Thu thập yêu cầu -> Tạo sản phẩm -> Khách hàng đánh giá"}],"id":"g29","part":3,"title":"Yêu cầu (Requirements)"},{"blocks":[{"level":1,"text":"Ngân sách Waterfall cứng nhắc và dễ đoán hơn"},{"level":1,"text":"Ngân sách Agile bao gồm thay đổi và tính linh hoạt"},{"level":1,"text":"Các dự án có ngân sách nghiêm ngặt sẽ phù hợp tốt với Waterfall"},{"level":1,"text":"Giám đốc dự án có thể cần giao tiếp với khách hàng để đảm bảo họ hiểu chi phí được tính vào các sản phẩm bàn giao của dự án như thế nào"},{"level":2,"text":"Anh ấy cũng có thể làm việc với nhóm để đảm bảo ước tính của họ phản ánh chính xác chi phí thực tế"},{"level":1,"text":"Các dự án Agile có thể sắp xếp ngân sách quanh các sản phẩm bàn giao cấp cao để tạo ra cách tiếp cận lai"},{"level":1,"text":"Khách hàng có ngân sách hạn chế có thể thích dự án Waterfall hơn"},{"level":1,"text":"Khách hàng muốn chi nhiều tiền hơn cho một sản phẩm được thiết kế riêng sẽ ưa chuộng cách tiếp cận Agile"},{"level":1,"text":"Lịch trình Agile linh hoạt hơn lịch trình Waterfall"},{"level":2,"text":"Lịch trình lỏng và linh hoạt"},{"level":2,"text":"Nhóm lập kế hoạch từng vòng lặp một"},{"level":1,"text":"Lịch trình Waterfall dễ đoán hơn lịch trình Agile"},{"level":2,"text":"Nhóm lập kế hoạch cho toàn bộ lịch trình dự án, bao gồm dòng thời gian và thời gian cần cho mỗi giai đoạn và công việc của dự án"}],"id":"g30","part":3,"title":"Ngân sách và Lịch trình (Budget and Schedule)"},{"blocks":[{"level":1,"text":"Các yếu tố môi trường khác nhau giữa Waterfall và Agile"},{"level":2,"text":"Văn hóa (Culture)"},{"level":2,"text":"Một nhóm Agile đòi hỏi cam kết, tin tưởng và hợp tác mạnh mẽ để đạt được giá trị tối đa"},{"level":2,"text":"Trong Waterfall, khách hàng nhận được sản phẩm gần như hoàn thiện"},{"level":2,"text":"Quy trình phát triển (Developmental Processes)"},{"level":2,"text":"Khi cân nhắc phát triển Agile, có thể khách hàng không thể đánh giá các phần tăng trưởng"},{"level":2,"text":"Có thể kiểm thử thủ công và tích hợp làm cho việc build thường xuyên trở nên tốn kém"},{"level":2,"text":"Tiêu chuẩn ngành (Industry Standards)"},{"level":2,"text":"Các ngành được quản lý chặt chẽ, đòi hỏi nhiều tài liệu hơn, cần một cấu trúc quản lý dự án đảm bảo khả năng truy vết đầy đủ"},{"level":2,"text":"Các công ty phụ thuộc nhiều vào tài liệu thường chọn Waterfall"}],"id":"g31","part":3,"title":"Các yếu tố môi trường (Environmental Factors)"},{"blocks":[{"level":1,"text":"Một dự án trải qua bốn giai đoạn bao trùm, được gọi là Initiation, Planning, Execution và Closing"},{"level":1,"text":"Làm việc nhóm là yếu tố thiết yếu cho thành công của dự án, vì nó đòi hỏi hợp tác với nhiều cá nhân đa dạng có nền tảng, góc nhìn, kỹ năng và tài năng khác nhau"},{"level":1,"text":"Việc tùy chỉnh cấu trúc nhóm cho phù hợp với nhu cầu của dự án là rất quan trọng"},{"level":1,"text":"Ma trận phân công trách nhiệm (Responsibility Assignment Matrix, RAM)"},{"level":2,"text":"Làm rõ vai trò và trách nhiệm trong dự án, đảm bảo hoàn thành công việc hiệu quả và giao tiếp tốt"},{"level":2,"text":"Nó phác thảo những người thực hiện (responsible), chịu trách nhiệm giải trình (accountable), được tham vấn (consulted) và được thông báo (informed) cho mỗi công việc"},{"level":1,"text":"Sự tham gia của các bên liên quan (stakeholder engagement) trong quản lý dự án bao gồm xây dựng và quản lý mối quan hệ với các bên liên quan xuyên suốt thời gian của dự án"},{"level":1,"text":"Đo lường hiệu suất trong dự án bao gồm các mục tiêu rõ ràng, có thể quan sát và đo lường được, được liệt kê trong tuyên ngôn dự án (project charter)"},{"level":2,"text":"Các chỉ số hiệu suất chính (Key Performance Indicators, KPIs)"},{"level":2,"text":"Mục tiêu SMART (SMART Objectives)"},{"level":2,"text":"Mục tiêu và kết quả chính (Objective and Key Results, OKRs)"},{"level":1,"text":"Tuyên ngôn dự án (project charter) phác thảo các thông số, mục đích, kỳ vọng và tầm nhìn của dự án"},{"level":1,"text":"Tuyên bố phạm vi (scope statement) cung cấp mô tả chi tiết về các yếu tố của dự án"},{"level":1,"text":"Một kế hoạch quản lý hồ sơ (records management plan) rất quan trọng trong giai đoạn khởi xướng của dự án để xử lý hiệu quả việc tạo ra tài liệu"},{"level":1,"text":"Buổi khởi động dự án (Project Kickoff)"},{"level":2,"text":"Cuộc họp trực tiếp nơi nhóm gặp nhau lần đầu để tạo ra sự hiểu biết chung về mục đích, mục tiêu và kế hoạch của dự án"}],"id":"g32","part":4,"title":"Khởi xướng dự án (Initiating the Project)"},{"blocks":[{"level":1,"text":"Làm việc nhóm là một yêu cầu tuyệt đối để dự án thành công"},{"level":1,"text":"Xác định những người sẽ thực hiện công việc"},{"level":1,"text":"Chọn các thành viên có kỹ năng phù hợp với công việc"},{"level":1,"text":"Giám đốc dự án (Project Manager, PM)"},{"level":2,"text":"Điều hành quản lý dự án hằng ngày"},{"level":2,"text":"Nhà tài trợ dự án (project sponsor) chịu trách nhiệm cuối cùng về thành công hay thất bại của dự án, và ủy quyền vận hành cho PM"},{"level":2,"text":"Trách nhiệm của PM"},{"level":2,"text":"Xây dựng nhóm dự án và đảm bảo nguồn lực"},{"level":2,"text":"Xây dựng tuyên ngôn dự án và xác định phạm vi của dự án"},{"level":2,"text":"Tạo các nhật ký và quy trình cần thiết cho dự án, bao gồm nhật ký vấn đề (issue log), nhật ký thay đổi (change log) và sổ đăng ký rủi ro (risk register)"},{"level":2,"text":"Đảm bảo các sản phẩm bàn giao của dự án được hoàn thành, bao gồm việc chắc chắn các thành viên có đúng kỹ năng và nguồn lực để hoàn thành các hoạt động trong danh sách hoạt động"},{"level":2,"text":"Chuẩn bị và trình bày các cập nhật tình trạng dự án"},{"level":2,"text":"Theo dõi tiến độ và tình trạng của dự án so với lịch trình và ngân sách"},{"level":2,"text":"Quản lý mối quan hệ với nhà cung cấp"},{"level":1,"text":"Chuyên viên phân tích nghiệp vụ (Business Analyst, BA)"},{"level":2,"text":"Cải thiện sản phẩm cuối cùng và hoạt động giữa bộ phận kinh doanh và bộ phận IT như một phiên dịch viên"},{"level":2,"text":"Trách nhiệm của BA"},{"level":2,"text":"Hỗ trợ xác định dự án"},{"level":2,"text":"Thu thập yêu cầu nghiệp vụ và yêu cầu kỹ thuật"},{"level":2,"text":"Đảm bảo yêu cầu luôn phù hợp với nhu cầu"},{"level":2,"text":"Diễn giải các yêu cầu nghiệp vụ"},{"level":2,"text":"Xác minh các sản phẩm bàn giao đối chiếu với yêu cầu"},{"level":2,"text":"Hỗ trợ kiểm thử và thẩm định sản phẩm"},{"level":1,"text":"Kiến trúc sư (Enterprise, Software, hoặc Cloud) (Architect)"},{"level":2,"text":"Thiết kế giải pháp bằng cách nhìn bao quát toàn tổ chức để xác định các hệ thống khác nhau tương tác như thế nào và đảm bảo các dự án đáp ứng yêu cầu giải pháp"},{"level":2,"text":"Trách nhiệm của các kiến trúc sư"},{"level":2,"text":"Thiết kế giải pháp"},{"level":2,"text":"Bản thiết kế hệ thống (system blueprints)"},{"level":2,"text":"Đánh giá các hệ thống theo tiêu chuẩn của tổ chức"},{"level":1,"text":"Lập trình viên hoặc Kỹ sư (Developer or Engineer)"},{"level":2,"text":"Có chuyên môn sâu trong lĩnh vực của mình, như phát triển front-end hoặc back-end, viết code, v.v."},{"level":2,"text":"Trách nhiệm của lập trình viên"},{"level":2,"text":"Viết code theo tiêu chuẩn"},{"level":2,"text":"Xây dựng sản phẩm theo kế hoạch dự án hoặc backlog sprint"},{"level":2,"text":"Báo cáo tiến độ phát triển cho giám đốc dự án hoặc chủ sở hữu sản phẩm"},{"level":1,"text":"Kiểm thử viên hoặc Đảm bảo chất lượng (Tester or Quality Assurance)"},{"level":2,"text":"Làm việc chặt chẽ với các lập trình viên để xây dựng phần mềm chất lượng, và giúp ngăn lỗi lọt vào production — một sai lầm có thể tốn kém và mất nhiều thời gian khắc phục"},{"level":1,"text":"Khách hàng hoặc Người dùng cuối (Customer or End-User)"},{"level":2,"text":"Một số nhóm dự án cũng sẽ có khách hàng hoặc người dùng cuối trong nhóm"},{"level":2,"text":"Họ có thể đưa ra những góc nhìn quý giá và thường đóng góp quan điểm về tính khả dụng và chức năng của sản phẩm"},{"level":1,"text":"Nhà cung cấp (Vendor)"},{"level":2,"text":"Bất kỳ bên thứ ba nào bạn làm việc cùng để mua sắm nguồn lực đều là nhà cung cấp, và bạn có thể làm việc với không nhà cung cấp nào hoặc nhiều nhà cung cấp trong một dự án"},{"level":2,"text":"Trách nhiệm của nhà cung cấp"},{"level":2,"text":"Cung cấp công việc như đã nêu trong hợp đồng"},{"level":2,"text":"Duy trì các thỏa thuận mức dịch vụ (service level agreements)"},{"level":2,"text":"Giữ các kênh giao tiếp rõ ràng, cởi mở cho quan hệ kinh doanh"},{"level":1,"text":"Bên liên quan (Stakeholder)"},{"level":2,"text":"Họ là những người hoặc nhóm bị ảnh hưởng bởi dự án, nhưng họ cũng có trách nhiệm đối với dự án"},{"level":2,"text":"Trách nhiệm của bên liên quan"},{"level":2,"text":"Phải hiểu mục đích của dự án và nó sẽ ảnh hưởng đến họ như thế nào"},{"level":2,"text":"Minh bạch về sự ủng hộ hoặc thiếu ủng hộ của họ"},{"level":2,"text":"Cung cấp phản hồi kịp thời về tiến độ của dự án"},{"level":1,"text":"Chuyên gia chuyên môn (Subject Matter Expert, SME)"},{"level":2,"text":"Người bạn tham vấn khi cần ai đó giải thích một chủ đề phức tạp một cách đơn giản hoặc giải quyết các vấn đề nâng cao"},{"level":1,"text":"Thành viên nhóm dự án (Project Team Member)"},{"level":2,"text":"Bất kỳ thành viên nào trong nhóm, bất kể chức danh hay vai trò, đều được coi là thành viên nhóm dự án"},{"level":1,"text":"Thành viên cốt lõi (Core Team Members)"},{"level":2,"text":"Còn được gọi là thành viên \"vận hành\" (operational) vì họ làm việc trong các hoạt động dự án hằng ngày"},{"level":1,"text":"Thành viên mở rộng (Extended Team Members)"},{"level":2,"text":"Họ làm việc cho dự án bán thời gian và có thể chia thời gian giữa nhiều dự án và công việc chuyên môn của mình"},{"level":1,"text":"Mỗi thành viên cần được xác định là thành viên cốt lõi hay thành viên mở rộng"},{"level":1,"text":"Các thành viên mở rộng sẽ có mức độ sẵn sàng khác nhau; nhu cầu kinh doanh, tình hình nhân sự và cấu trúc tổ chức ảnh hưởng đến mức độ sẵn sàng của mỗi cá nhân"},{"level":1,"text":"Thành viên chuyên môn (functional member) có thể cam kết toàn phần cho việc thực hiện dự án"},{"level":1,"text":"Các thành viên có thể được phân loại thêm theo phần trăm thời gian sẵn sàng, mức độ sẵn sàng theo giai đoạn, hoặc sẵn sàng theo yêu cầu"}],"id":"g33","part":4,"title":"Vai trò và trách nhiệm của nhóm (Team Roles and Responsibilities)"},{"blocks":[{"level":1,"text":"Xác định các thành viên nhóm dự án dựa trên kỹ năng, mức độ sẵn sàng và vai trò"},{"level":1,"text":"Chọn đúng người cho công việc"},{"level":1,"text":"Xây dựng nhóm dự án thường là một quá trình liên tục"},{"level":2,"text":"Xác định phạm vi dự án"},{"level":2,"text":"Lựa chọn các thành viên tiềm năng"},{"level":1,"text":"Khi nhóm đang được thành lập, PM thường là người chọn các thành viên"},{"level":2,"text":"Các nhà tài trợ cũng có thể chỉ định một số thành viên chủ chốt từ sớm trong dự án"},{"level":1,"text":"Bạn cũng muốn ghi lại thêm thông tin về nhóm dự án"},{"level":2,"text":"Vị trí công việc (Job Position)"},{"level":2,"text":"Mức độ sẵn sàng (Availability)"},{"level":2,"text":"Nhóm con hoặc cách phân nhóm (Sub team or Grouping)"},{"level":2,"text":"Trách nhiệm (Responsibilities)"},{"level":2,"text":"Phương thức liên lạc ưa thích (Preferred Contact Methods)"},{"level":2,"text":"Người quản lý (Manager)"},{"level":2,"text":"Tổ chức (Organization)"},{"level":1,"text":"Điều này dẫn chúng ta đến việc xây dựng sơ đồ tổ chức dự án (project organizational chart)"},{"level":2,"text":"Sơ đồ này sẽ trông giống một sơ đồ tổ chức thông thường, nhưng sẽ thể hiện các giao diện dự án của nhóm"}],"id":"g34","part":4,"title":"Xây dựng nhóm dự án (Building the Project Team)"},{"blocks":[{"level":1,"text":"Ma trận phân công trách nhiệm (Responsibility Assignment Matrix, RAM)"},{"level":2,"text":"Làm rõ ai chịu trách nhiệm hoàn thành và quản lý các hoạt động trong dự án"},{"level":1,"text":"Các thành viên cần biết phải làm gì và làm việc với ai"},{"level":1,"text":"RAM giúp tạo cảm giác sở hữu dự án và mô tả cách các thành viên và các bên liên quan làm việc với các sản phẩm bàn giao của dự án"},{"level":1,"text":"Các vai trò rơi vào bốn nhóm sau: người thực hiện (responsible), người chịu trách nhiệm giải trình (accountable), người được tham vấn (consulted) và người được thông báo (informed)"},{"level":1,"text":"RAM được tạo lần đầu trong giai đoạn khởi xướng dự án (project initiation phase)"},{"level":1,"text":"Các bước tạo RAM"},{"level":2,"text":"Liệt kê các hoạt động của dự án, sẽ được đặt trong cột đầu tiên của ma trận"},{"level":2,"text":"Liệt kê các thành viên nhóm dự án, các bên liên quan và các bên khác dọc theo hàng đầu của các cột"},{"level":2,"text":"Xác định những người chịu trách nhiệm thực hiện công việc"},{"level":2,"text":"Đánh dấu R cho những người chịu trách nhiệm thực hiện (responsible) các hoạt động"},{"level":2,"text":"Đánh dấu A cho những người chịu trách nhiệm giải trình (accountable) các hoạt động"},{"level":2,"text":"Đánh dấu C cho những người được tham vấn (consulted)"},{"level":2,"text":"Đánh dấu I cho những người cần được thông báo (informed)"},{"level":2,"text":"Bước tùy chọn: Nếu nó giúp ích cho bạn và nhóm, hãy dùng mã màu (color-coding) và nhóm để làm sơ đồ dễ đọc hơn"}],"id":"g35","part":4,"title":"Ma trận phân công trách nhiệm (Responsibility Assignment Matrix, RAM)"},{"blocks":[{"level":1,"text":"Mối quan hệ giữa con người với nhau thực sự quan trọng"},{"level":1,"text":"Một cái bắt tay chắc, giao tiếp bằng mắt, sự lịch sự và trao đổi kịp thời sẽ giúp ích rất nhiều khi bạn xây dựng mối quan hệ và thu hút sự tham gia của các bên liên quan"},{"level":1,"text":"Sự tham gia của các bên liên quan (stakeholder engagement) là cách PM xây dựng và quản lý mối quan hệ với các bên liên quan xuyên suốt vòng đời của dự án"},{"level":1,"text":"Các bên liên quan sẽ đặt câu hỏi đào sâu và thách thức các giả định"},{"level":1,"text":"Kỹ năng mềm cực kỳ quan trọng và nên nằm trong \"túi công cụ\" tưởng tượng của mọi giám đốc dự án"},{"level":1,"text":"4 bước để thu hút sự tham gia của các bên liên quan"},{"level":2,"text":"Xác định các bên liên quan chính"},{"level":2,"text":"Ưu tiên các bên liên quan"},{"level":2,"text":"Hiểu các bên liên quan"},{"level":2,"text":"Xây dựng kế hoạch thu hút sự tham gia"},{"level":1,"text":"Các bên liên quan ưu tiên cao nhất cần được thu hút thường xuyên và tích cực, còn các bên liên quan ưu tiên thấp nhất chỉ cần chú ý tối thiểu"},{"level":1,"text":"Lưới tác động (Impact Grid)"},{"level":2,"text":"Một biểu đồ ma trận đặt các giá trị cao-thấp cho hai biến số của bên liên quan"},{"level":2,"text":"Nó đo lường mức độ các bên liên quan có thể ảnh hưởng đến hướng đi của dự án và mức độ dự án tác động đến họ"},{"level":2,"text":"Lưới có bốn góc phần tư theo thứ tự ưu tiên"},{"level":2,"text":"Quyền lực cao / Tác động cao (High Power/High Impact)"},{"level":2,"text":"Các bên liên quan có nhiều thứ để đạt được nhất và có quyền lực lớn nhất"},{"level":2,"text":"Điều quan trọng là làm việc với họ để xây dựng sự ủng hộ và đảm bảo họ hài lòng với tiến độ của dự án."},{"level":2,"text":"Quyền lực cao / Tác động thấp (High Power/Low Impact)"},{"level":2,"text":"Các bên liên quan có đủ ảnh hưởng để có thể làm chệch hướng một dự án nếu họ muốn"},{"level":2,"text":"Dự án ít tác động đến họ, nên họ có thể có mức quan tâm thấp hơn"},{"level":2,"text":"Quyền lực thấp / Tác động cao (Low Power/High Impact)"},{"level":2,"text":"Các bên liên quan có ít quyền lực để thay đổi dự án, nên họ ít có khả năng gây gián đoạn hơn"},{"level":2,"text":"Công việc của họ sẽ thay đổi đáng kể vì dự án"},{"level":2,"text":"Quyền lực thấp / Tác động thấp (Low Power/Low Impact)"},{"level":2,"text":"Các bên liên quan có ít quyền lực hoặc tác động đến dự án"},{"level":2,"text":"Bạn có thể sẽ thấy mức quan tâm thấp nhất ở góc phần tư này, nhưng tình hình có thể thay đổi"},{"level":1,"text":"Kế hoạch thu hút sự tham gia của các bên liên quan bao gồm các mục sau"},{"level":2,"text":"Bên liên quan (Stakeholder)"},{"level":2,"text":"Liệt kê cá nhân hoặc nhóm"},{"level":2,"text":"Đầu mối liên lạc (Point of Contact)"},{"level":2,"text":"Nếu bên liên quan không phải là một cá nhân, hãy liệt kê người đại diện cho bên liên quan đó"},{"level":2,"text":"Quyền lực (Power)"},{"level":2,"text":"Liệt kê mức quyền lực theo lưới Quyền lực/Tác động (Power/Impact Grid)"},{"level":2,"text":"Ảnh hưởng (Influence)"},{"level":2,"text":"Liệt kê mức tác động của họ theo lưới Quyền lực/Tác động"},{"level":2,"text":"Giai đoạn dự án (Project Phase)"},{"level":2,"text":"Liệt kê các giai đoạn dự án mà bạn sẽ cần thu hút sự tham gia của họ"},{"level":2,"text":"Nhu cầu tham gia (Engagement Needs)"},{"level":2,"text":"Mô tả những gì họ cần hoặc lý do họ là bên liên quan chính"},{"level":2,"text":"Cách tiếp cận thu hút (Engagement Approach)"},{"level":2,"text":"Liệt kê loại hình thu hút bạn sẽ thực hiện theo lưới Quyền lực/Tác động"},{"level":2,"text":"Phương thức (Methods)"},{"level":2,"text":"Ghi lại cách bạn sẽ giao tiếp với họ"},{"level":2,"text":"Tần suất (Frequency)"},{"level":2,"text":"Liệt kê một thuật ngữ mô tả mức độ thường xuyên bạn sẽ thu hút sự tham gia của bên liên quan"},{"level":1,"text":"Kế hoạch thu hút sự tham gia của các bên liên quan không giống với kế hoạch quản lý giao tiếp (communication management plan)"}],"id":"g36","part":4,"title":"Thu hút sự tham gia của các bên liên quan (Stakeholder Engagement)"},{"blocks":[{"level":1,"text":"Một khởi đầu mạnh mẽ cho dự án giúp chúng ta tạo ra sự hiểu biết chung với tất cả các thành viên và các bên liên quan đang làm việc trong dự án"},{"level":2,"text":"Một sự hiểu biết chung, cùng chia sẻ về dự án tạo ra môi trường nơi mọi người có cùng nhận thức về phạm vi, dòng thời gian, cấu trúc nhóm và mục đích của dự án"},{"level":1,"text":"Một nền tảng vững chắc giúp ngăn ngừa hiểu sai, mất tài liệu và phình phạm vi (scope creep) xuyên suốt dự án"},{"level":1,"text":"Các sản phẩm công việc (artifacts) có thể cho cái nhìn sâu sắc về cách các dự án tương tự đã được thực hiện"},{"level":1,"text":"Quan sát các bài học kinh nghiệm từ trải nghiệm quá khứ và tránh các chướng ngại"},{"level":1,"text":"Chuẩn bị cho một dự án thường bắt đầu bằng nghiên cứu"},{"level":1,"text":"Sản phẩm công việc của dự án (Project Artifact)"},{"level":2,"text":"Hạng mục hữu hình được tạo ra và sử dụng bởi mọi người xuyên suốt dự án"},{"level":2,"text":"Các ví dụ khác về sản phẩm công việc của dự án"},{"level":2,"text":"Video"},{"level":2,"text":"Bản ghi âm"},{"level":2,"text":"Các hạng mục công việc (Work Items)"},{"level":2,"text":"Sơ đồ dữ liệu (Data Diagrams)"},{"level":1,"text":"Nghiên cứu các sản phẩm công việc hiện có giúp bạn nhanh chóng định hướng trong dự án"}],"id":"g37","part":4,"title":"Tài liệu khởi xướng dự án (Project Initiation Documents)"},{"blocks":[{"level":1,"text":"Khi nói về hiệu suất, nó đề cập đến các mục tiêu dự án rõ ràng, có thể quan sát và đo lường được, được liệt kê trong tuyên ngôn dự án"},{"level":1,"text":"Các PM sử dụng các cách tiếp cận có cấu trúc, hướng đến mục tiêu để đo lường hiệu suất"},{"level":2,"text":"Các chỉ số hiệu suất chính (Key Performance Indicators, KPIs)"},{"level":2,"text":"Nó chỉ đo lường các chỉ số quan trọng nhất"},{"level":2,"text":"Các KPI được đo lường thường xuyên một cách liên tục"},{"level":2,"text":"KPI bao gồm mục tiêu (targets) và số liệu thực tế (actuals)"},{"level":2,"text":"Mục tiêu (Target)"},{"level":2,"text":"Một giá trị hoặc tập hợp các giá trị mô tả phạm vi hiệu suất chấp nhận được"},{"level":2,"text":"KPI đo lường cả chỉ số dẫn dắt (leading indicators) và chỉ số phản ánh (lagging indicators)"},{"level":2,"text":"Chỉ số phản ánh (Lagging Indicators)"},{"level":2,"text":"Đây là các chỉ số phản ánh chỉ có thể ghi nhận sau khi công việc hoàn thành và mô tả sự thành công đã đạt được của một dự án hoặc quy trình"},{"level":2,"text":"Chỉ số dẫn dắt (Leading Indicators)"},{"level":2,"text":"Đây là các chỉ số dự báo; nếu chúng tốt thì kết quả thực sự mong muốn sẽ được cải thiện"},{"level":2,"text":"Mục tiêu SMART (SMART Objectives)"},{"level":2,"text":"Một cách đơn giản để tạo mục tiêu"},{"level":2,"text":"Một từ viết tắt của"},{"level":2,"text":"SPECIFIC"},{"level":2,"text":"Giải thích chính xác những gì chúng ta muốn đạt được"},{"level":2,"text":"MEASURABLE"},{"level":2,"text":"Có chỉ số thành công có thể định lượng được"},{"level":2,"text":"ACHIEVABLE"},{"level":2,"text":"Cần thực tế về mục tiêu"},{"level":2,"text":"RELEVANT"},{"level":2,"text":"Giúp bạn được thăng chức hoặc chuyển vị trí"},{"level":2,"text":"TIME-BOUND"},{"level":2,"text":"Có ngày kết thúc mục tiêu"},{"level":2,"text":"Đánh giá nó theo từng tiêu chí SMART và tinh chỉnh lại"},{"level":2,"text":"Mục tiêu và kết quả chính (Objective and Key Results, OKRs)"},{"level":2,"text":"Các tổ chức áp dụng OKR để đạt kết quả nhanh chóng"},{"level":2,"text":"Chúng được đặt ra đầy khát vọng và hơi vượt tầm với"},{"level":2,"text":"Chúng thúc đẩy các nhóm mang lại giá trị mà họ không nghĩ là có thể"},{"level":2,"text":"OKR tạo ra một phát biểu mục tiêu gồm hai phần: mục tiêu và kết quả chính"},{"level":2,"text":"Các mục tiêu này theo cách tiếp cận \"ít mà chất\" (\"less is more\")"},{"level":1,"text":"KPI giúp bạn ổn định và bảo vệ hệ thống"},{"level":1,"text":"SMART là một phương pháp để viết các mục tiêu vững chắc"},{"level":1,"text":"OKR được dùng để tạo các mục tiêu ngắn hạn và tạo ra sự thay đổi"},{"level":1,"text":"Lộ trình dự án (Project Roadmap)"},{"level":2,"text":"Tài liệu cấp cao chia sẻ các điểm tiến độ chính, như việc triển khai các tính năng mới"},{"level":2,"text":"Rất trực quan và giống với định dạng, mức độ chi tiết mà bạn có thể đọc trong một thông cáo báo chí"},{"level":1,"text":"Biểu đồ cột mốc (Milestone Chart)"},{"level":2,"text":"Mô tả các sự kiện cột mốc, là các điểm kiểm tra của dự án"},{"level":2,"text":"Chúng trông giống một dòng thời gian và vẽ các hạn chót, điểm kiểm tra và ngày quan trọng trong suốt quá trình của dự án"},{"level":1,"text":"Biểu đồ Gantt (Gantt Chart)"},{"level":2,"text":"Thể hiện mối quan hệ và sự phụ thuộc giữa các công việc"},{"level":2,"text":"Dùng biểu đồ Gantt trong các giai đoạn Planning, Execution và Closing"}],"id":"g38","part":4,"title":"Đo lường hiệu suất & Biểu đồ dòng thời gian (Performance Measures & Timeline Charts)"},{"blocks":[{"level":1,"text":"Tuyên ngôn dự án (Project Charter)"},{"level":2,"text":"Một tài liệu chính thức, ngắn gọn phác thảo các thông số của dự án"},{"level":2,"text":"Được tạo trong giai đoạn Initiation và giúp nhóm, các bên liên quan, nhà tài trợ và PM đạt được sự đồng thuận về tầm quan trọng của dự án và cách nó sẽ được thực hiện"},{"level":2,"text":"Một số lợi ích của tuyên ngôn dự án (Several Benefits of Project Charter)"},{"level":2,"text":"Làm rõ mục đích và kỳ vọng của dự án cho các bên liên quan"},{"level":2,"text":"Làm rõ vai trò và mức độ quyền hạn của PM"},{"level":2,"text":"Quy trình tạo tuyên ngôn dự án đơn giản hóa (Simplified Creation Process of Project Charter)"},{"level":2,"text":"Dùng một mẫu (template) sẽ giúp ích rất nhiều vì bạn sẽ liên tục dùng lại các trường thông tin giống nhau"},{"level":2,"text":"Tài liệu nên ngắn gọn và đơn giản"},{"level":2,"text":"Dùng ngôn ngữ rõ ràng và súc tích"},{"level":2,"text":"Hợp tác với nhóm của bạn để chốt dòng thời gian và đánh giá rủi ro"},{"level":2,"text":"4 nhóm thông tin chung (4 General Categories of Information)"},{"level":2,"text":"Thông tin chung về dự án (General Project Information)"},{"level":2,"text":"Một phần đầu (header) với thông tin chuẩn dùng cho mục đích hành chính"},{"level":2,"text":"Tên dự án (Project Name)"},{"level":2,"text":"Mô tả (Description)"},{"level":2,"text":"Số phiên bản và ngày (Version Number and Date)"},{"level":2,"text":"Giám đốc dự án (Project Manager)"},{"level":2,"text":"Nhà tài trợ dự án (Project Sponsor)"},{"level":2,"text":"Tầm nhìn dự án (Project Vision)"},{"level":2,"text":"Bao gồm các trường xây dựng luận chứng kinh doanh và đặt kỳ vọng cho kết quả của dự án"},{"level":2,"text":"Mục tiêu (Objectives)"},{"level":2,"text":"Mục đích (Purpose)"},{"level":2,"text":"Phạm vi sơ bộ (Preliminary Scope)"},{"level":2,"text":"Tiêu chí thành công (Success Criteria)"},{"level":2,"text":"Lợi ích mong đợi (Expected Benefits)"},{"level":2,"text":"Tổ chức (Con người) (Organization (People))"},{"level":2,"text":"Những người và nhóm bị ảnh hưởng bởi dự án"},{"level":2,"text":"Các bên liên quan (Stakeholders)"},{"level":2,"text":"Khách hàng (Customers)"},{"level":2,"text":"Các vai trò dự án (Project Roles)"},{"level":2,"text":"Các thành viên nhóm (Team Members)"},{"level":2,"text":"Tổ chức dự án (Project Organization)"},{"level":2,"text":"Tổng quan triển khai (Implementation Overview)"},{"level":2,"text":"Các yếu tố sẽ ảnh hưởng đến dự án trong quá trình triển khai"},{"level":2,"text":"Ngân sách (Budget)"},{"level":2,"text":"Rủi ro (Risks)"},{"level":2,"text":"Ràng buộc (Constraints)"},{"level":2,"text":"Dòng thời gian (Timelines)"},{"level":2,"text":"Các cột mốc (Milestones)"},{"level":2,"text":"Yêu cầu nguồn lực (Resource Requirements)"},{"level":1,"text":"Tuyên ngôn dự án là phạm vi và ranh giới & sản phẩm bàn giao được tóm tắt"},{"level":1,"text":"Tuyên bố phạm vi là mô tả chi tiết về nhiều yếu tố"},{"level":2,"text":"Tuyên bố phạm vi là một tài liệu sống (living document)"},{"level":2,"text":"Trong tuyên bố phạm vi sơ bộ, bạn sẽ có những mục sau"},{"level":2,"text":"Mô tả phạm vi dự án (Project Scope Description)"},{"level":2,"text":"Tóm tắt ý định và mục đích của dự án"},{"level":2,"text":"Tiêu chí chấp nhận dự án (Project Acceptance Criteria)"},{"level":2,"text":"Mô tả chi tiết các kết quả thành công có thể đo lường trông như thế nào"},{"level":2,"text":"Sản phẩm bàn giao của dự án (Project Deliverables)"},{"level":2,"text":"Đặt ranh giới dự án và xác định những gì nhóm sẽ bàn giao cho phạm vi"},{"level":2,"text":"Các hạng mục loại trừ của dự án (Project Exclusions)"},{"level":2,"text":"Đặt ranh giới dự án cho những gì ngoài phạm vi và những gì dự án sẽ không bàn giao"},{"level":2,"text":"Giả định và ràng buộc (Assumptions and Constraints)"},{"level":2,"text":"Phần giả định liệt kê các giả định chung của nhóm dự án, và phần ràng buộc liệt kê các ràng buộc đã biết trong suốt vòng đời của dự án"}],"id":"g39","part":4,"title":"Tuyên ngôn dự án & Tuyên bố phạm vi (Project Charter & Scope Statement)"},{"id":"g40","part":4,"title":"Quản lý hồ sơ (Records Management)","blocks":[{"level":1,"text":"Một tài liệu (document) là một hiện vật hữu hình"},{"level":2,"text":"Nó chứa dữ liệu (data), bao gồm sự kiện, số liệu và thông tin"},{"level":1,"text":"Hồ sơ (Record)"},{"level":2,"text":"Một hiện vật cần thiết để vận hành dự án hoặc doanh nghiệp"},{"level":2,"text":"Không phải mọi tài liệu đều là hồ sơ"},{"level":1,"text":"Kế hoạch quản lý hồ sơ (records management plan) của bạn nên bao gồm những hồ sơ nào cần giữ lại và cách phân loại, bảo vệ dữ liệu"},{"level":2,"text":"Các loại hiện vật phổ biến thuộc kế hoạch này"},{"level":2,"text":"Hiện vật quản lý dự án (Project Management Artifact)"},{"level":2,"text":"Hiện vật dùng để quản lý dự án, ví dụ như ngân sách dự án và kế hoạch gắn kết các bên liên quan (stakeholder engagement plan)"},{"level":2,"text":"Hiện vật dự án (Project Artifact)"},{"level":2,"text":"Tài liệu được tạo ra để thúc đẩy dự án, ví dụ như các tài liệu bắt buộc và bản vẽ kỹ thuật (blueprints)"},{"level":2,"text":"Tài liệu pháp lý (Legal Document)"},{"level":2,"text":"Tạo ra các hợp đồng dự án và các thỏa thuận ràng buộc pháp lý khác"},{"level":2,"text":"Giao tiếp (Communication)"},{"level":2,"text":"Bao gồm biên bản họp, báo cáo tình trạng và các giao tiếp bằng văn bản"},{"level":1,"text":"Thông tin dự án (Project Information)"},{"level":2,"text":"Là tài sản của công ty, và một số thông tin trong đó tạo lợi thế cạnh tranh so với đối thủ"},{"level":1,"text":"4 loại dữ liệu (Data)"},{"level":2,"text":"Dữ liệu công khai (Public Data)"},{"level":2,"text":"Thông tin có trên website công ty và trong các hồ sơ công khai"},{"level":2,"text":"Dữ liệu nội bộ (Internal Data)"},{"level":2,"text":"Bất kỳ ai trong công ty đều có thể tiếp cận"},{"level":2,"text":"Dữ liệu bảo mật (Confidential Data)"},{"level":2,"text":"Thông tin chỉ dành cho người dùng được ủy quyền, theo vai trò hoặc theo từng trường hợp cụ thể"},{"level":2,"text":"Dữ liệu hạn chế (Restricted Data)"},{"level":2,"text":"Là dữ liệu tuyệt mật mà quyền truy cập bị hạn chế nghiêm ngặt"},{"level":1,"text":"Việc phân loại tài liệu phụ thuộc vào dữ liệu mà nó chứa"},{"level":1,"text":"Các yêu cầu của kế hoạch quản lý hồ sơ (Records Management Plan)"},{"level":2,"text":"Kế hoạch tuân thủ chính sách của tổ chức"},{"level":2,"text":"Các hồ sơ cần được sắp xếp có tổ chức và dễ tìm kiếm"},{"level":2,"text":"Kế hoạch có thể truy cập được đối với người dùng được ủy quyền"},{"level":2,"text":"Kế hoạch cần thiết lập các kênh giao tiếp được chấp nhận"},{"level":1,"text":"Các thành phần của kế hoạch quản lý hồ sơ"},{"level":2,"text":"Tạo lập (Creation)"},{"level":2,"text":"Xác định quy ước đặt tên, chủ sở hữu tệp và ai được phép tạo tệp"},{"level":2,"text":"Lưu trữ và truy xuất (Storage and Retrieval)"},{"level":2,"text":"Xác định nơi nhóm sẽ lưu trữ tệp và cấu trúc tổ chức tệp"},{"level":2,"text":"Lưu trữ lâu dài và xử lý (Archival and Disposition)"},{"level":2,"text":"Xác định cách xử lý tệp trùng lặp và tệp lỗi thời, cũng như thời gian lưu trữ hồ sơ sau khi dự án kết thúc"}]},{"id":"g41","part":5,"title":"Cuộc họp khởi động (Kickoff)","blocks":[{"level":1,"text":"Kickoff là bước cuối cùng của giai đoạn khởi tạo (Initiation), khi nhóm đã có điều lệ dự án được phê duyệt và kèm theo một tuyên bố phạm vi sơ bộ"},{"level":1,"text":"Cuộc họp kickoff vừa mang tính nghi lễ vừa mang tính thực tiễn"},{"level":1,"text":"Mục đích của kickoff là tạo ra sự thấu hiểu chung cho mọi người"},{"level":1,"text":"Các thành viên nhóm và các bên liên quan (stakeholders) nên có kỳ vọng rõ ràng và thống nhất về dự án"},{"level":1,"text":"Các cuộc họp kickoff sẽ khác nhau về mức độ trang trọng và cấu trúc. Điều phối các cuộc họp hiệu quả (Facilitating Effective Meetings)"}]},{"id":"g42","part":5,"title":"Điều phối các cuộc họp hiệu quả (Facilitating Effective Meetings)","blocks":[{"level":1,"text":"Giao tiếp kém có thể khiến một dự án chìm rất nhanh"},{"level":1,"text":"Giao tiếp đồng bộ (Synchronous Communication)"},{"level":2,"text":"Cho phép trao đổi thông tin ngay lập tức và các cuộc trò chuyện chuyên sâu, nhưng yêu cầu mọi người phải sẵn sàng cùng lúc"},{"level":1,"text":"Giao tiếp không đồng bộ (Asynchronous Communication)"},{"level":2,"text":"Mang lại sự linh hoạt nhưng gây ra độ trễ và khả năng tin nhắn không được đọc"},{"level":1,"text":"Giao tiếp chính thức (formal communication) tuân theo các kênh chính thức, trong khi giao tiếp không chính thức (informal communication) diễn ra một cách tự nhiên trong tổ chức"},{"level":1,"text":"Các thách thức giao tiếp có thể phát sinh do rào cản ngôn ngữ, địa lý, công nghệ và văn hóa"},{"level":1,"text":"Các cuộc họp có ba vai trò chính"},{"level":2,"text":"Đối tượng mục tiêu (Target Audience)"},{"level":2,"text":"Người điều phối (Facilitator)"},{"level":2,"text":"Thư ký ghi chép (Scribe)"},{"level":1,"text":"Các cuộc họp thông tin (informative meetings) nhằm phổ biến thông tin đến đối tượng tham dự"},{"level":1,"text":"Các cuộc họp quyết định (decisive meetings), còn gọi là cuộc họp ra quyết định (decision-making meetings), có một hoặc nhiều người tham dự đưa ra lựa chọn liên quan đến dự án"},{"level":1,"text":"4 loại chính của cuộc họp cộng tác (collaborative meetings)"},{"level":2,"text":"Nhóm tập trung (Focus Groups)"},{"level":2,"text":"Hội thảo (Workshops)"},{"level":2,"text":"Đánh giá ứng dụng (Application Reviews)"},{"level":2,"text":"Phiên động não (Brainstorming Sessions)"},{"level":1,"text":"Việc giữ tổ chức có nề nếp đối với một quản lý dự án (project manager) là vô cùng quan trọng do số lượng lớn cuộc họp, email và tương tác liên quan"},{"level":1,"text":"Xung đột là một phần không thể tránh khỏi trong cả đời sống cá nhân và nghề nghiệp, và cần được giải quyết một cách có trách nhiệm"}]},{"id":"g43","part":5,"title":"Các phương thức giao tiếp (Communication Methods)","blocks":[{"level":1,"text":"Các phương thức hay cách thức giao tiếp (communication methods/modalities) mô tả cách thông tin được chia sẻ/tiếp nhận"},{"level":1,"text":"4 yếu tố chính của các phương thức giao tiếp"},{"level":2,"text":"Thời điểm (Timing)"},{"level":2,"text":"Định dạng (Format)"},{"level":2,"text":"Mức độ trang trọng (Formality)"},{"level":2,"text":"Đối tượng (Audience)"},{"level":1,"text":"2 loại giao tiếp"},{"level":2,"text":"Giao tiếp đồng bộ (Synchronous Communication)"},{"level":2,"text":"Còn gọi là giao tiếp thời gian thực (real-time communication), ví dụ như cuộc gọi điện thoại, hội nghị qua điện thoại (teleconference) hoặc cuộc họp trực tiếp"},{"level":2,"text":"Giao tiếp đồng bộ có lợi vì bạn nhận được mọi thông tin cần thiết nhanh chóng và có thể giải tỏa nhầm lẫn ngay lập tức"},{"level":2,"text":"Nhược điểm là mọi người đều cần phải sẵn sàng cùng một lúc"},{"level":2,"text":"Giao tiếp không đồng bộ (Asynchronous Communication)"},{"level":2,"text":"Xảy ra khi việc trao đổi thông tin có độ trễ, ví dụ như email và bình luận trong một tài liệu dùng chung"},{"level":2,"text":"Giao tiếp không đồng bộ mang lại sự linh hoạt; bạn có thể giao tiếp với nhiều người cùng lúc"},{"level":2,"text":"Độ trễ có thể không thể chấp nhận được đối với các vấn đề khẩn cấp, và chúng có thể khiến những câu hỏi đơn giản bị kéo dài"},{"level":1,"text":"Các cân nhắc về định dạng (Format Considerations)"},{"level":2,"text":"Giao tiếp bằng văn bản (Written Communication)"},{"level":2,"text":"Bất cứ hình thức nào mà việc trao đổi diễn ra qua tin nhắn viết tay hoặc đánh máy"},{"level":2,"text":"Ví dụ bao gồm thư từ cho đến tin nhắn tức thì, email và chữ nổi Braille"},{"level":2,"text":"Giao tiếp bằng lời (Verbal Communication)"},{"level":2,"text":"Được thực hiện bằng lời nói, ví dụ như qua tương tác trực tiếp, cuộc gọi điện thoại, hội nghị qua điện thoại, v.v."},{"level":2,"text":"Giao tiếp phi ngôn ngữ (Nonverbal Communication)"},{"level":2,"text":"Đề cập đến các tín hiệu khác được gửi đi trong lúc giao tiếp bằng lời, ví dụ như ngôn ngữ cơ thể và ngoại hình"},{"level":1,"text":"Giao tiếp chính thức (Formal Communication)"},{"level":2,"text":"Đại diện cho các kênh giao tiếp chính thức, là những kênh có chủ đích, theo thủ tục, nơi thông tin được lưu chuyển và các quyết định được ghi chép lại"},{"level":2,"text":"Đánh giá cổng giai đoạn dự án (Project Phase Gate Reviews)"},{"level":2,"text":"Hệ thống trợ giúp (Help Desk Systems)"},{"level":2,"text":"Thông báo công ty (Company Memos)"},{"level":2,"text":"Các kênh giao tiếp chính thức thường cụ thể và cứng nhắc"},{"level":1,"text":"Giao tiếp không chính thức (Informal Communication)"},{"level":2,"text":"Mô tả mọi luồng thông tin không chính thức trong một tổ chức"},{"level":2,"text":"Bao gồm cuộc trò chuyện thoải mái giữa đồng nghiệp, chuyện nhóm trước khi cuộc họp bắt đầu và giao tiếp phi ngôn ngữ trong cuộc họp"},{"level":1,"text":"Hiểu rõ đối tượng và mức độ trang trọng trong ngôn ngữ của bạn"},{"level":1,"text":"Giao tiếp nội bộ (Internal Communication)"},{"level":2,"text":"Bao gồm người nhận làm việc trong tổ chức"},{"level":2,"text":"Đối tượng có thể gồm các thành viên từ các dự án, nhóm hoặc phòng ban khác nhau, nhưng mọi người đều làm việc cho cùng một công ty"},{"level":1,"text":"Giao tiếp bên ngoài (External Communication)"},{"level":2,"text":"Bao gồm người nhận làm việc bên ngoài tổ chức"},{"level":2,"text":"Thường trang trọng, trau chuốt và được chọn lọc"},{"level":2,"text":"Nhìn chung, cần hết sức thận trọng khi giao tiếp với họ"}]},{"id":"g44","part":5,"title":"Các thách thức trong giao tiếp (Communication Challenges)","blocks":[{"level":1,"text":"Rào cản ngôn ngữ, địa lý, công nghệ và văn hóa đều có thể gây thách thức cho giao tiếp"},{"level":1,"text":"Chọn các định dạng giao tiếp phù hợp hoặc đưa thêm các biện pháp hỗ trợ bổ sung, ví dụ như có phiên dịch viên trong các cuộc họp trực tiếp và bật phụ đề chi tiết (closed captioning)"},{"level":1,"text":"Những người cần nhiều thời gian hơn để hiểu nội dung có thể thích giao tiếp không đồng bộ, bằng văn bản hoặc được ghi lại"},{"level":1,"text":"Các nhóm phân tán về mặt địa lý ngày càng phổ biến hơn bao giờ hết"},{"level":1,"text":"Nhận thức và tôn trọng sự khác biệt về múi giờ"},{"level":1,"text":"Nếu nhóm trải rộng, tốt hơn nên chọn giao tiếp không đồng bộ"},{"level":1,"text":"Tổ chức nhiều cuộc họp, dùng email và chat, hoặc ghi lại các cuộc họp"},{"level":1,"text":"Các rào cản công nghệ bao gồm mọi thách thức giao tiếp liên quan đến công nghệ"},{"level":1,"text":"Một số thành viên nhóm có thể có internet chậm hơn hoặc phần cứng cũ hơn"},{"level":1,"text":"Bất cứ điều gì bạn đầu tư để loại bỏ các rào cản công nghệ đều sẽ giúp đồng đội vui vẻ, hiệu quả và năng suất hơn"},{"level":1,"text":"Văn hóa bao gồm các phong tục xã hội, hành vi, thói quen và niềm tin chung"},{"level":2,"text":"Nó có thể đề cập đến bất kỳ nhóm nào có thể quan sát được, bao gồm độ tuổi, giới tính, chủ sử dụng lao động, nghề nghiệp và sở thích"},{"level":1,"text":"Các công ty thường hướng tới việc tạo ra một văn hóa nơi làm việc mạnh mẽ, giúp gắn kết mọi người làm việc cho công ty"},{"level":1,"text":"Các PM cần nhận thức về các nền văn hóa trong nhóm dự án của mình và tác động của chúng"}]},{"id":"g45","part":5,"title":"Các vai trò trong cuộc họp (Meeting Roles)","blocks":[{"level":1,"text":"Cuộc họp là nỗ lực của tập thể, và một số vai trò giúp cuộc họp đi đúng hướng"},{"level":1,"text":"3 vai trò trong một cuộc họp"},{"level":2,"text":"Người tham dự/Đối tượng mục tiêu (Attendees/Target Audience)"},{"level":2,"text":"Nhóm người cần có mặt trong cuộc họp"},{"level":2,"text":"Những người tham dự trong danh sách nên được lựa chọn có chủ đích để giữ cho nhóm nhỏ gọn và hiệu quả"},{"level":2,"text":"Xác định mục đích và kết quả mong đợi của cuộc họp"},{"level":2,"text":"Chọn những người có thể biến điều đó thành hiện thực"},{"level":2,"text":"Người điều phối (Facilitator)"},{"level":2,"text":"Định hướng tiến trình của cuộc họp"},{"level":2,"text":"Người điều phối theo dõi dòng chảy của cuộc họp và chuyển hướng cuộc trò chuyện"},{"level":2,"text":"Thư ký ghi chép (Scribe)"},{"level":2,"text":"Ghi chép cho cuộc họp, bao gồm biên bản họp (meeting minutes), các mục hành động (action items) và các việc theo dõi (follow ups)"},{"level":2,"text":"Mọi người tham dự đều hỗ trợ thư ký ghi chép trong bất kỳ cuộc họp nào bằng cách trả lời câu hỏi, cung cấp bối cảnh hoặc chia sẻ thông tin qua chat hay email"},{"level":2,"text":"Các hướng dẫn sau đây hữu ích nếu bạn chọn triển khai vai trò này"},{"level":2,"text":"Các cuộc họp tạo ra hồ sơ chính thức (như họp Hội đồng quản trị)"},{"level":2,"text":"Khi cần hồ sơ bằng văn bản và việc điều phối được dự đoán là tốn sức"},{"level":2,"text":"Một phiên mà cuộc trò chuyện sẽ diễn ra nhanh chóng"}]});
